// Reads STOCK_DATA (from stock_data.js, generated by generate_dashboard_data.py)
// and lets you search across whichever companies you've generated locally.
// No API calls — search just filters the data already sitting in the file.

const searchInput = document.getElementById("stock-search");
const searchButton = document.getElementById("search-button");
const suggestionsBox = document.getElementById("suggestions");
const quickPicksBox = document.getElementById("quick-picks");
const statusEl = document.getElementById("status");
const dashboardEl = document.getElementById("dashboard");

let companies = [];

document.addEventListener("DOMContentLoaded", () => {
  companies =
    typeof STOCK_DATA !== "undefined" ? Object.values(STOCK_DATA) : [];

  if (companies.length === 0) {
    setStatus(
      "No local data yet. Run generate_dashboard_data.py in your project " +
        "folder — it creates stock_data.js, which this page reads automatically."
    );
    return;
  }

  renderQuickPicks();
  // show the first company by default so the page isn't empty on load
  selectCompany(companies[0]);
});

// ---------- Helpers ----------

function setStatus(message, isError = false) {
  statusEl.textContent = message || "";
  statusEl.classList.toggle("is-error", isError);
}

function formatMoney(value) {
  const num = Number(value);
  if (Number.isNaN(num)) return "—";
  return `$${num.toFixed(2)}`;
}

function formatVolume(value) {
  const num = Number(value);
  if (Number.isNaN(num)) return "—";
  return num.toLocaleString("en-US");
}

function themeColors() {
  const styles = getComputedStyle(document.documentElement);
  return {
    ink: styles.getPropertyValue("--ink").trim(),
    gold: styles.getPropertyValue("--gold").trim(),
    gain: styles.getPropertyValue("--gain").trim(),
    loss: styles.getPropertyValue("--loss").trim(),
  };
}

function baseScales(colors, extra = {}) {
  return {
    x: {
      ticks: { color: colors.ink, maxTicksLimit: 8, font: { family: "IBM Plex Mono", size: 10 } },
      grid: { display: false },
    },
    y: {
      ticks: { color: colors.ink, font: { family: "IBM Plex Mono", size: 10 } },
      grid: { color: "rgba(0,0,0,0.08)" },
      ...extra,
    },
  };
}

// ---------- Quick picks ----------

function renderQuickPicks() {
  quickPicksBox.innerHTML = "";
  companies.forEach((company) => {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip";
    chip.textContent = company.companyName;
    chip.addEventListener("click", () => {
      searchInput.value = company.companyName;
      selectCompany(company);
    });
    quickPicksBox.appendChild(chip);
  });
  quickPicksBox.hidden = false;
}

function markActiveChip(symbol) {
  quickPicksBox.querySelectorAll(".chip").forEach((chip, i) => {
    chip.classList.toggle("is-active", companies[i].symbol === symbol);
  });
}

// ---------- Local search ----------

function findMatches(query) {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return [];

  return companies.filter(
    (c) =>
      c.symbol.toLowerCase() === normalized ||
      c.symbol.toLowerCase().includes(normalized) ||
      c.companyName.toLowerCase().includes(normalized)
  );
}

searchInput.addEventListener("input", () => {
  const matches = findMatches(searchInput.value);
  renderSuggestions(matches);
});

searchInput.addEventListener("keydown", (event) => {
  if (event.key === "Enter") {
    event.preventDefault();
    runSearch();
  }
});

searchButton.addEventListener("click", runSearch);

document.addEventListener("click", (event) => {
  if (!event.target.closest(".search-container")) {
    hideSuggestions();
  }
});

function runSearch() {
  const query = searchInput.value.trim();
  if (!query) return;

  hideSuggestions();
  const matches = findMatches(query);

  if (matches.length === 0) {
    dashboardEl.hidden = true;
    setStatus(
      `No local data for "${query}" yet. Set SYMBOL/COMPANY_NAME in ` +
        `generate_dashboard_data.py, re-run it, and refresh this page.`,
      true
    );
    return;
  }

  selectCompany(matches[0]);
}

function renderSuggestions(matches) {
  if (matches.length === 0) {
    hideSuggestions();
    return;
  }

  suggestionsBox.innerHTML = "";
  matches.slice(0, 8).forEach((company) => {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "suggestion-item";
    item.innerHTML = `
      <span class="suggestion-name">${company.companyName}</span>
      <span class="suggestion-symbol">${company.symbol}</span>
    `;
    item.addEventListener("click", () => {
      searchInput.value = company.companyName;
      hideSuggestions();
      selectCompany(company);
    });
    suggestionsBox.appendChild(item);
  });

  suggestionsBox.hidden = false;
}

function hideSuggestions() {
  suggestionsBox.hidden = true;
  suggestionsBox.innerHTML = "";
}

// ---------- Rendering ----------

function selectCompany(company) {
  setStatus(null);
  dashboardEl.hidden = false;
  markActiveChip(company.symbol);

  renderHeader(company);
  renderTodayStats(company.today, company.asOf);
  renderHistoryChart(company);
  renderForecastChart(company);
  renderTimelineChart(company);
  renderOutlook(company.nextDayPrediction, company.modelPerformance);
  renderActualVsPredicted(company);
  renderFeatureImportance(company.featureImportance);

  // scroll the dashboard into view so "Look up" visibly takes you to the graphs
  dashboardEl.scrollIntoView({ behavior: "smooth", block: "start" });
}

function renderHeader(company) {
  document.getElementById("company-name").textContent = company.companyName;
  document.getElementById("company-symbol").textContent = company.symbol;
  document.title = `Ledger — ${company.companyName} Dashboard`;

  const historyTitle = document.getElementById("history-chart-title");
  if (historyTitle) historyTitle.textContent = `${company.companyName} closing stock price`;

  const avpTitle = document.getElementById("avp-chart-title");
  if (avpTitle) avpTitle.textContent = `${company.companyName} actual vs predicted next-day close`;

  const forecastTitle = document.getElementById("forecast-chart-title");
  if (forecastTitle) forecastTitle.textContent = `${company.companyName} — 3-month forecast`;

  const timelineTitle = document.getElementById("timeline-chart-title");
  if (timelineTitle) {
    timelineTitle.textContent = `${company.companyName} predicted price — 2020 through 3 months from today`;
  }
}

function renderTodayStats(today, asOf) {
  document.getElementById("price").textContent = formatMoney(today.close);

  const changeEl = document.getElementById("change");
  const arrow = today.change >= 0 ? "▲" : "▼";
  changeEl.textContent = `${arrow} ${formatMoney(Math.abs(today.change))} (${today.changePercent}%)`;
  changeEl.classList.toggle("positive", today.change >= 0);
  changeEl.classList.toggle("negative", today.change < 0);

  document.getElementById("stat-open").textContent = formatMoney(today.open);
  document.getElementById("stat-prev-close").textContent = formatMoney(today.previousClose);
  document.getElementById("stat-range").textContent = `${formatMoney(today.low)} – ${formatMoney(today.high)}`;
  document.getElementById("stat-volume").textContent = formatVolume(today.volume);
  document.getElementById("stat-date").textContent = asOf;
}

let historyChartInstance = null;

function renderHistoryChart(company) {
  const canvas = document.getElementById("history-chart");
  const colors = themeColors();

  if (historyChartInstance) historyChartInstance.destroy();

  historyChartInstance = new Chart(canvas, {
    type: "line",
    data: {
      labels: company.closePriceHistory.map((row) => row.date),
      datasets: [
        {
          label: "Close price",
          data: company.closePriceHistory.map((row) => row.close),
          borderColor: colors.gold,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: baseScales(colors),
    },
  });
}

let forecastChartInstance = null;

function renderForecastChart(company) {
  const canvas = document.getElementById("forecast-chart");
  if (!canvas || !company.forecast3Month) return;

  const colors = themeColors();

  // show the last 60 actual trading days flowing into the forecast, so the
  // transition from real data to prediction is visible
  const recentHistory = company.closePriceHistory.slice(-60);
  const forecast = company.forecast3Month;

  const historyLabels = recentHistory.map((row) => row.date);
  const historyValues = recentHistory.map((row) => row.close);
  const forecastLabels = forecast.map((row) => row.date);
  const forecastValues = forecast.map((row) => row.predictedClose);

  const labels = [...historyLabels, ...forecastLabels];
  const actualSeries = [...historyValues, ...forecastLabels.map(() => null)];
  const forecastSeries = [
    ...historyLabels.map(() => null),
    historyValues[historyValues.length - 1], // connects the two lines visually
    ...forecastValues.slice(1),
  ];

  if (forecastChartInstance) forecastChartInstance.destroy();

  forecastChartInstance = new Chart(canvas, {
    type: "line",
    data: {
      labels,
      datasets: [
        {
          label: "Actual close",
          data: actualSeries,
          borderColor: colors.ink,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
        {
          label: "3-month forecast",
          data: forecastSeries,
          borderColor: colors.gain,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          borderDash: [4, 3],
          pointRadius: 0,
          tension: 0.1,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          display: true,
          labels: { color: colors.ink, font: { family: "IBM Plex Mono", size: 10 } },
        },
      },
      scales: baseScales(colors),
    },
  });
}

let timelineChartInstance = null;

function renderTimelineChart(company) {
  const canvas = document.getElementById("timeline-chart");
  if (!canvas || !company.predictionTimeline) return;

  const colors = themeColors();
  const rows = company.predictionTimeline;

  const labels = rows.map((row) => row.date);
  const actualSeries = rows.map((row) => (row.actual === null ? null : row.actual));
  const predictedSeries = rows.map((row) => row.predicted);

  if (timelineChartInstance) timelineChartInstance.destroy();

  timelineChartInstance = new Chart(canvas, {
    type: "line",
    data: {
      labels,
      datasets: [
        {
          label: "Actual",
          data: actualSeries,
          borderColor: colors.ink,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
        {
          label: "Predicted",
          data: predictedSeries,
          borderColor: colors.gain,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          display: true,
          labels: { color: colors.ink, font: { family: "IBM Plex Mono", size: 10 } },
        },
      },
      scales: baseScales(colors),
    },
  });
}

function renderOutlook(prediction, performance) {
  document.getElementById("outlook-next-close").textContent = formatMoney(
    prediction.predictedClose
  );

  const changeEl = document.getElementById("outlook-next-change");
  const pct = prediction.predictedChangePercent;
  changeEl.textContent = `${pct >= 0 ? "▲" : "▼"} ${Math.abs(pct).toFixed(3)}%`;
  changeEl.classList.toggle("positive", pct >= 0);
  changeEl.classList.toggle("negative", pct < 0);

  document.getElementById("outlook-mae").textContent =
    `${performance.mae.toFixed(5)} / ${performance.baselineMae.toFixed(5)}`;
  document.getElementById("outlook-r2").textContent = performance.r2.toFixed(4);
}

let avpChartInstance = null;
let avpRecentChartInstance = null;

function renderActualVsPredicted(company) {
  const rows = company.actualVsPredicted;
  const colors = themeColors();

  const fullDatasets = {
    labels: rows.map((row) => row.date),
    actual: rows.map((row) => row.actual),
    predicted: rows.map((row) => row.predicted),
  };

  const recentRows = rows.slice(-100);
  const recentDatasets = {
    labels: recentRows.map((row) => row.date),
    actual: recentRows.map((row) => row.actual),
    predicted: recentRows.map((row) => row.predicted),
  };

  if (avpChartInstance) avpChartInstance.destroy();
  if (avpRecentChartInstance) avpRecentChartInstance.destroy();

  avpChartInstance = drawAvpChart("avp-chart", fullDatasets, colors);
  avpRecentChartInstance = drawAvpChart("avp-recent-chart", recentDatasets, colors);
}

function drawAvpChart(canvasId, dataset, colors) {
  const canvas = document.getElementById(canvasId);

  return new Chart(canvas, {
    type: "line",
    data: {
      labels: dataset.labels,
      datasets: [
        {
          label: "Actual",
          data: dataset.actual,
          borderColor: colors.ink,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
        {
          label: "Predicted",
          data: dataset.predicted,
          borderColor: colors.gain,
          backgroundColor: "transparent",
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.1,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          display: true,
          labels: { color: colors.ink, font: { family: "IBM Plex Mono", size: 10 } },
        },
      },
      scales: baseScales(colors),
    },
  });
}

let importanceChartInstance = null;

function renderFeatureImportance(importance) {
  const canvas = document.getElementById("importance-chart");
  const colors = themeColors();

  if (importanceChartInstance) importanceChartInstance.destroy();

  importanceChartInstance = new Chart(canvas, {
    type: "bar",
    data: {
      labels: importance.map((row) => row.feature),
      datasets: [
        {
          label: "Importance",
          data: importance.map((row) => row.importance),
          backgroundColor: colors.gold,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: baseScales(colors, { beginAtZero: true }),
    },
  });
}








// ADD this call inside renderDashboard(), alongside your other render*() calls:
renderHorizonSummary(company.horizonSummary);

// ADD this function anywhere in the file
function renderHorizonSummary(horizons) {
  if (!horizons) return;

  const render = (elId, h) => {
    const el = document.getElementById(elId);
    if (!el) return;
    const arrow = h.medianChangePercent >= 0 ? "▲" : "▼";
    el.innerHTML = `${formatMoney(h.medianPrice)} <span style="opacity:.7">(${arrow} ${Math.abs(h.medianChangePercent).toFixed(2)}%)</span>`;
    el.classList.toggle("positive", h.medianChangePercent >= 0);
    el.classList.toggle("negative", h.medianChangePercent < 0);
  };

  render("horizon-5day", horizons.fiveDay);
  render("horizon-1month", horizons.oneMonth);
  render("horizon-3month", horizons.threeMonth);
}